{
  "findings": [
    {
      "check_id": "CKV_GCP_25",
      "title": "GKE private cluster is not enabled",
      "resource": "google_container_cluster.k8sexample",
      "severity": "MEDIUM",
      "explanation": "The cluster does not enable private nodes, so worker nodes can receive public IP addresses and have increased network exposure."
    },
    {
      "check_id": "AVD-GCP-0056",
      "title": "GKE network policy is not enabled",
      "resource": "google_container_cluster.k8sexample",
      "severity": "MEDIUM",
      "explanation": "No network policy configuration is present, allowing unrestricted pod-to-pod communication within the cluster."
    },
    {
      "check_id": "CKV_GCP_23",
      "title": "GKE Alias IP ranges are not enabled",
      "resource": "google_container_cluster.k8sexample",
      "severity": "MEDIUM",
      "explanation": "The cluster lacks an ip_allocation_policy block, so VPC-native Alias IP networking is not explicitly enabled."
    }
  ],
  "patched_code": "variable "master_ipv4_cidr_block" {
  description = "RFC1918 /28 CIDR block used by the GKE private control plane"
  type        = string
}

resource "google_container_cluster" "k8sexample" {
  name                    = "${var.vault_user}-k8s-cluster"
  description             = "example k8s cluster"
  zone                    = "${var.gcp_zone}"
  initial_node_count      = "${var.initial_node_count}"
  enable_kubernetes_alpha = "true"
  enable_legacy_abac      = "true"

  master_auth {
    username = "${var.master_username}"
    password = "${var.master_password}"

    client_certificate_config {
      issue_client_certificate = true
    }
  }

  private_cluster_config {
    enable_private_nodes   = true
    master_ipv4_cidr_block = var.master_ipv4_cidr_block
  }

  ip_allocation_policy {}

  network_policy {
    enabled  = true
    provider = "CALICO"
  }

  addons_config {
    network_policy_config {
      disabled = false
    }
  }

  node_config {
    machine_type = "${var.node_machine_type}"
    disk_size_gb = "${var.node_disk_size}"
    oauth_scopes = [
      "https://www.googleapis.com/auth/compute",
      "https://www.googleapis.com/auth/devstorage.read_only",
      "https://www.googleapis.com/auth/logging.write",
      "https://www.googleapis.com/auth/monitoring"
    ]
  }
}
",
  "fix_summary": "Enabled private GKE nodes, VPC-native Alias IP allocation, and Calico network policy enforcement. Added a required input for a deployment-specific, non-overlapping private control-plane /28 CIDR rather than hard-coding a potentially conflicting range."
}
